import json
import re


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def norm(name):
    s = re.sub(r"[^a-z0-9 ]+", " ", str(name or "").lower())
    return re.sub(r"\s+", " ", s).strip()


def money_close(a, b, tolerance=0.01):
    try:
        return abs(float(a) - float(b)) <= tolerance
    except Exception:
        return False


def extract_id(link):
    if not isinstance(link, dict):
        return ""
    url = ((link.get("links") or {}).get("self")) or ""
    m = re.search(r"/(\d+)(?:$|\?)", str(url))
    return m.group(1) if m else ""


def patient_display_name(patient_id):
    # Invoice.patient is link-only (no embedded name - confirmed against
    # docs.api.cliniko.com/openapi/invoice), so the name needs its own lookup.
    if not patient_id:
        return ""
    try:
        p = api.connectors.invoke(server="cliniko-patients", tool="get_patient", args={"id": patient_id})
        return (str(p.get("first_name") or "") + " " + str(p.get("last_name") or "")).strip()
    except Exception:
        return ""


# Same detection as Payment reconciliation exceptions (Cliniko Invoice.status: 10 Open, 20 Paid,
# 30 Closed, 40 Open credit - confirmed against docs.api.cliniko.com/openapi/invoice) - this
# automation reuses the exact same match, just frames it as a green light rather than a problem.
CLINIKO_STATUS_OPEN = 10


def find_open_invoices(business_id):
    try:
        result = api.connectors.invoke(
            server="cliniko-billing", tool="list_invoices",
            args={"q": ["business_id:=" + business_id, "status:=" + str(CLINIKO_STATUS_OPEN)], "per_page": 100},
        )
        return (result or {}).get("invoices") or []
    except Exception:
        return []


def find_recent_xero_payments(tenant_id):
    try:
        result = api.connectors.invoke(
            server="xero-accounting", tool="list_payments",
            args={"xero_tenant_id": tenant_id, "page": 1},
        )
        return (result or {}).get("Payments") or (result if isinstance(result, list) else [])
    except Exception:
        return []


practices = []
try:
    entries = api.files.list(path="PracticeManager/Practices", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    slug = str(fname)[:-5]
    practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
    if practice:
        practices.append({"slug": slug, "practice": practice})

ready_by_practice = []
for p in practices:
    business_id = str(p["practice"].get("cliniko_business_id") or "")
    tenant_id = str(p["practice"].get("xero_tenant_id") or "")
    if not business_id or not tenant_id:
        continue

    open_invoices = find_open_invoices(business_id)
    payments = find_recent_xero_payments(tenant_id)

    found = []
    for inv in open_invoices:
        inv_number = str(inv.get("number") or "")
        patient_id = extract_id(inv.get("patient"))
        patient_name = patient_display_name(patient_id)
        amount = inv.get("total_amount")

        match = None
        for pay in payments:
            pay_invoice = (pay or {}).get("Invoice") or {}
            pay_number = str(pay_invoice.get("InvoiceNumber") or "")
            pay_contact = str(((pay_invoice.get("Contact") or {}).get("Name")) or "")
            pay_amount = (pay or {}).get("Amount")
            if inv_number and pay_number and inv_number == pay_number:
                match = pay
                break
            if patient_name and pay_contact and norm(patient_name) == norm(pay_contact) and money_close(amount, pay_amount):
                match = pay
                break

        if match:
            found.append({
                "invoice_number": inv_number or str(inv.get("id") or ""),
                "patient_name": patient_name or "Unknown patient",
                "amount": amount,
            })

    if found:
        ready_by_practice.append({
            "slug": p["slug"], "name": p["practice"].get("name") or p["slug"],
            "reviewer_id": p["practice"].get("reviewer_id") or "", "ready": found,
        })

if not ready_by_practice:
    outcome = "none_ready"
else:
    for sec in ready_by_practice:
        lines = "\n".join(
            "- " + r["patient_name"] + ", invoice " + r["invoice_number"] + ", $" + str(r["amount"]) + " - payment confirmed in Xero"
            for r in sec["ready"]
        )
        api.workq.create(
            title="Paid and ready to dispatch: " + sec["name"] + " (" + str(len(sec["ready"])) + ")",
            scope="org",
            description=(
                "Payment has landed in Xero for these - cleared to order tests or dispense herbs. "
                "Cliniko's invoice record is read-only and will keep showing Open until closed by hand:\n\n" + lines
            ),
            priority="normal",
            assignee_ids=[sec["reviewer_id"]] if sec["reviewer_id"] else None,
            labels=["healthcare-practice-management", "dispatch"],
        )
    outcome = "flagged"
